cd ~/academy-labs/p12-3 && mkdir -p recorded
cat > score.mjs <<'EOF'
// Scores recorded runs of one eval case with the case's own grader files, the way claude plugin eval does:
// a run's score is the weighted share of graders that passed, a case's score is the mean over its runs,
// and Δ is WITH minus W/OUT. Only the free graders (regex, tool_used) are implemented here.
import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";

const [caseDir, recordedFile] = process.argv.slice(2);

const frontmatter = (text) => Object.fromEntries(text.split("---")[1].trim().split("\n").map((line) => {
  const i = line.indexOf(":");
  let value = line.slice(i + 1).trim().replace(/^'(.*)'$/, "$1");
  return [line.slice(0, i).trim(), /^\d+$/.test(value) ? Number(value) : value];
}));

const graders = readdirSync(join(caseDir, "graders")).filter((f) => f.endsWith(".md"))
  .map((f) => ({ name: f.replace(/\.md$/, ""), weight: 1, ...frontmatter(readFileSync(join(caseDir, "graders", f), "utf8")) }));

const passes = (g, run) => {
  if (g.type === "regex") return new RegExp(g.pattern, g.flags ?? "").test(run.lastMessage);
  if (g.type === "tool_used") {
    const match = g.input_match ? new RegExp(g.input_match) : null;
    const n = run.toolCalls.filter((c) => c.tool === g.tool && (!match || match.test(JSON.stringify(c.input)))).length;
    return n >= (g.min ?? 1) && n <= (g.max ?? Infinity);
  }
  throw new Error(`${g.name}: the lab scorer only runs regex and tool_used graders`);
};

// In a two-arm run, "the skill fired" can never pass without the plugin, so it is shown but not scored.
const indicator = (g) => g.arm === "with-only" || (g.type === "tool_used" && g.tool === "Skill" && g.arm !== "both");
const scored = graders.some((g) => !indicator(g)) ? graders.filter((g) => !indicator(g)) : graders;
const total = scored.reduce((sum, g) => sum + g.weight, 0);
const runScore = (run) => scored.filter((g) => passes(g, run)).reduce((sum, g) => sum + g.weight, 0) / total;
const mean = (xs) => xs.reduce((a, b) => a + b, 0) / xs.length;

const { arms } = JSON.parse(readFileSync(recordedFile, "utf8"));
console.log(`scored: ${scored.map((g) => g.name).join(", ")}   indicator: ${graders.filter((g) => !scored.includes(g)).map((g) => g.name).join(", ") || "none"}`);
const score = {};
for (const [arm, runs] of Object.entries(arms)) {
  score[arm] = mean(runs.map(runScore));
  const fired = graders.filter((g) => !scored.includes(g)).map((g) => `  ${g.name} ${runs.filter((r) => passes(g, r)).length}/${runs.length}`).join("");
  console.log(`${arm.padEnd(8)} ${runs.map((r) => runScore(r).toFixed(2)).join("  ")}   mean ${score[arm].toFixed(2)}${fired}`);
}
const delta = score.with - score.without;
console.log(`WITH ${score.with.toFixed(2)}  W/OUT ${score.without.toFixed(2)}  Δ ${delta >= 0 ? "+" : ""}${delta.toFixed(2)}`);
EOF
